import { defineConfig } from '@playwright/test';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

// The UI in WebKit (the engine inside every iPhone and iPad web view) at phone size, with touch. The UI reads fixtures
// generated by `npm run fixtures` (from the database, through `wb fixture`) instead of calling Rust.
//
// The tests serve the UI of this checkout, on a port of its own: `npm run dev` keeps 1420 (Tauri's devUrl), and every
// checkout or worktree gets a port picked from its path (1430-1929), so a vite another checkout has running is never
// the one tested (2026-11-08: a worktree's run passed against the main checkout's UI). WB_UI_PORT picks the port by
// hand. The server is never reused: Playwright starts this checkout's vite and stops it after, and if the port is
// taken the run fails, loudly, instead of testing someone else's UI.
const root = fileURLToPath(new URL('.', import.meta.url)).toLowerCase();
const fromPath = 1430 + (createHash('sha1').update(root).digest().readUInt32BE(0) % 500);
const port = Number(process.env.WB_UI_PORT) || fromPath;
const url = `http://127.0.0.1:${port}/`;

export default defineConfig({
  testDir: 'ui/tests',
  outputDir: 'test-results',
  reporter: [['list']],
  use: { baseURL: url },
  webServer: { command: `npm run dev -- --port ${port} --strictPort`, url, reuseExistingServer: false },
  projects: [
    { name: 'webkit-phone', use: { browserName: 'webkit', viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 } },
    { name: 'webkit-desktop', use: { browserName: 'webkit', viewport: { width: 1440, height: 900 } } },
    // The real app is WebView2 (Edge's Chromium, so the installed Edge is used): the writing specs run in it too (`npx playwright test --project chromium-editor`)
    { name: 'chromium-editor', testMatch: ['writing.spec.ts', 'slash.spec.ts', 'atlink.spec.ts', 'blockhandle.spec.ts', 'notebook-*.spec.ts', 'lists-chips.spec.ts'], use: { browserName: 'chromium', channel: 'msedge', viewport: { width: 1440, height: 900 } } },
  ],
});
